import{_ as o}from"./chunks/FetchSearch.vue_vue_type_script_setup_true_lang.DfXirNUF.js";import{T as r}from"./chunks/ZigenTrain.Dqsl4Kww.js";import{Z as t}from"./chunks/ZigenMap.B-BYwaXD.js";import{o as c,c as d,ag as n,m as i,G as l,a}from"./chunks/framework.BQoish8B.js";import"./chunks/share.C05s20Z4.js";import"./chunks/html2canvas-pro.esm.C7wW9koE.js";import"./chunks/advancedSchedule.CyVEQGBC.js";import"./chunks/cascadeStyles.D4fE9S2h.js";/* empty css                                                                          */const s={class:"zigen-font"},h={class:"zigen-font"},z=JSON.parse('{"title":"潇明","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"ime/xiaoming.md","filePath":"ime/xiaoming.md"}'),m={name:"ime/xiaoming.md"},V=Object.assign(m,{setup(u){return(g,e)=>(c(),d("div",null,[e[0]||(e[0]=n('<h1 id="潇明" tabindex="-1">潇明 <a class="header-anchor" href="#潇明" aria-label="Permalink to &quot;潇明&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p><a href="https://github.com/Dieken/code_genie/tree/55e783c3973b125d3f56baac534b796c76df87a5/moling/xiaoming-output/output-20261011-061440/thread-06" target="_blank" rel="noreferrer">潇明</a>输入方案，是结合宇浩拆分和<a href="https://github.com/hertz-hwang/rime-xx" target="_blank" rel="noreferrer">潇湘</a>输入方案单字编码格式的五码自定码，由 @恷子 设计，@qq3qq 实现。</p><ol><li>25 键方案，字根编码 ASB，大码 A 取 ZDFJKEI 外 19 个字母，小码 S 和补码 B 都取 DFJKEI 六个字母： <ul><li>小码来自常用字字根的声母，映射如下： <ul><li>D: 0 h y</li><li>E: b s w</li><li>F: d g t</li><li>I: f m z</li><li>J: l p q r x</li><li>K: c j k n</li></ul></li><li>补码来自字根首笔笔画，映射如下： <ul><li>横 K，竖 I，撇 J，点 F，逆时针折 E，顺时针折 D；</li></ul></li><li>非常用字字根无声母，因此小码取补码，相当于字根编码为 ABB；</li><li>补码只用在字根字里，有时候文档或者 QQ 群里在讨论多根字编码、词编码、简码时会提到小码 B，其实指的是小码 S，有的人习惯用 A 指代大码，用 B 指代小码，但本文特意用 S 指代小码，因为来自声母；</li><li>举例： <ul><li><code>烏</code>: 大码 B, 小码 E（w 映射到 E)，补码 J(字根首笔的撇映射到 J)；</li><li><span class="zigen-font"></span>: 大码 B(与 <code>烏</code> 聚类），小码 J（无音的非常用字字根，小码取补码），补码 J(字根首笔的撇映射到 J)，潇明的设计类似魔灵，并不会因为字根形状相近就归并成同一个编码，而是严格遵守常用字字根用声母映射小码，其它字根小码取补码的规则。</li></ul></li></ul></li><li>字根聚类程度接近灵明；</li><li>单字编码： <ul><li>单根字：<code>A1S1B1</code>，就是字根的编码，例如 <code>烏</code> Bej；</li><li>双根字: <code>A1S1A2S2</code>，就是首根的大小码加上次根的大小码，例如 <code>好</code> 由 <code>女</code> Cke 和 <code>子</code> Gid 组成，所以编码了 CkGi；</li><li>三根字：<code>A1S1A2A3S3</code>，就是首根的大小码、次根的大码加上末根的大小码，例如 <code>做</code> 由 <code>亻</code> Wjj、 <code>古</code> Nfk 和 <code>攵</code> Qjj 组成，所以编码为 WjNQj；</li><li>四根及以上：<code>A1S1A2A3Az</code>，就是首根的大小码、次根的大码、三根的大码、末根的大码，例如 <code>靈</code> 由 <code>雨</code> Qdk、 <code>口</code> Aki、 <code>口</code> Aki、 <code>人</code> Vjj 组成，所以编码为 QdAAV；</li></ul></li><li>简码： <ul><li>6 个一键上屏无理简码字： 不 K, 在 F, 是 J，我 I，的 D，了 E，不需要加空格；</li><li>19 个空格上屏的一码简字：<code>A1_</code>，就是首根大码，如 <code>一</code> Hdk 的简码为 H 加空格；</li><li>19 x 19 = 361 个二键上屏的二码简字：<code>A1A2</code>，就是首根大码加上次根大码，如 <code>他</code> WjLd 的简码为 WL ，不需要加空格;</li><li>三键上屏简码：<code>A1S1Sz</code>，就是首根大码、首根小码加上末根小码，如 <code>去</code> UfLe 的简码为 Ufe；</li></ul></li><li>词组： <ul><li>二字词：取<strong>首末、首末</strong>根，<code>AS A + A AS</code>，也即首字首根大小码，首字末根大码（如非首根），加次字首根大码(如非末根)、次字末根大小码，截断为 5 码； <ul><li>举例： <code>一人</code> ，Hdk Vjj，词编码为 HdVj;</li><li>举例： <code>中國</code> ，AkTi SiOAH，词编码为 AkTSH；</li></ul></li><li>三字词：取<strong>末、末、首末</strong>根，<code>AS + A + A A</code>, 也即首字末根大小码，加次字末根大码，加末字首根大码、末字末根大码； <ul><li>举例： <code>新中國</code> ，VjVQk AkTi SiOAH，词编码为 QkTSH；</li></ul></li><li>四字及以上词：取<strong>末、末、末、末</strong>根，<code>AS + A + A + A</code>，也即首字末根大小码，加次字末根大码，加三字末根大码，加末字末根大码； <ul><li>举例， <code>哭哭啼啼</code> ，AkAAj AkAAj AkTPV AkTPV，词编码为 AjAVV；</li></ul></li><li>取末根的原因是尽可能的跳过偏旁部首，增强词组编码的离散度；</li><li><a href="https://github.com/hertz-hwang/CHS/blob/main/data/kc6000.txt" target="_blank" rel="noreferrer">科学测评 6 万词</a>（去掉两个带字母的词）词重 4.108%， 虽然词重比较低，但潇明依然是主单方案，词的规则设计故意脱离取首根次根的惯例，增加了一点难度以获得更好离散度；</li></ul></li></ol><p>使用<a href="https://ceping.shurufa.app" target="_blank" rel="noreferrer">宇浩测评</a>测得的性能指标：</p><ul><li>通用规范 8105 字静重： 61 非首选字；</li><li>常用国字 4808 字静重： 12 非首选字；</li><li>知乎简体·频率降序动重： 0.42‱；</li><li>北语简体·频率降序动重： 0.84‱；</li><li>台标繁体·频率降序动重： 1.02‱；</li><li>知乎简体字频全码当量： 1.2323；</li><li>北语简体字频全码当量： 1.2329；</li><li>台标繁体字频全码当量： 1.2741；</li><li>简码效率： 北语字频 50 简码 3.357，100 简码 3.148，所有简码 2.691；</li></ul><h2 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h2><ul><li>感谢朱宇浩制作的优质拆分和灵明、星陈优质方案；</li><li>感谢 <a href="https://github.com/hertz-hwang" target="_blank" rel="noreferrer">@荒</a> 的<a href="https://github.com/hertz-hwang/code_genie" target="_blank" rel="noreferrer">码灵</a>优化程序和<a href="https://github.com/hertz-hwang/rime-xx" target="_blank" rel="noreferrer">潇湘</a> 方案；</li><li>感谢 @恷子 的<a href="https://github.com/Dieken/code_genie/commit/741a1571b37505806e4058c2c6952935f6aa57a5" target="_blank" rel="noreferrer">方案设计</a>；</li></ul><h2 id="拆分" tabindex="-1">拆分 <a class="header-anchor" href="#拆分" aria-label="Permalink to &quot;拆分&quot;">​</a></h2>',9)),i("div",s,[l(o,{chaifenUrl:"/chaifen.json",zigenUrl:"/zigen-xiaoming.csv",rule:"xiaoming"})]),e[1]||(e[1]=i("h2",{id:"字根",tabindex:"-1"},[a("字根 "),i("a",{class:"header-anchor",href:"#字根","aria-label":'Permalink to "字根"'},"​")],-1)),l(t,{"default-scheme":"xiaoming",alwaysVisibleZigens:"卩丂丩屮丱髟廾豕彡",chaifenUrl:"/chaifen.json","column-min-width":"1rem",schemeCnName:"潇明",customEmptyKeyLabels:{k:"一码上屏字 不",f:"一码上屏字 在",j:"一码上屏字 是",i:"一码上屏字 我",d:"一码上屏字 的",e:"一码上屏字 了"},customFooter:"QQ群: 544760766 · 本图链接: https://shurufa.app/ime/xiaoming"}),e[2]||(e[2]=i("h2",{id:"练习",tabindex:"-1"},[a("练习 "),i("a",{class:"header-anchor",href:"#练习","aria-label":'Permalink to "练习"'},"​")],-1)),i("div",h,[l(r,{name:"xiaoming",chaifenUrl:"/chaifen.json",zigenUrl:"/zigen-xiaoming.csv",range:[0],mode:"both",rule:"xiaoming"})])]))}});export{z as __pageData,V as default};
